// All implementations must embed UnimplementedVaultServiceServer
// for forward compatibility.
type VaultServiceServer interface {
	ListConnections(context.Context, *ListConnectionsRequest) (*ListConnectionsResponse, error)
	SaveConnection(context.Context, *SaveConnectionRequest) (*SaveConnectionResponse, error)
	DeleteConnection(context.Context, *DeleteConnectionRequest) (*DeleteConnectionResponse, error)
	ListTargets(context.Context, *ListTargetsRequest) (*ListTargetsResponse, error)
	SaveTarget(context.Context, *SaveTargetRequest) (*SaveTargetResponse, error)
	DeleteTarget(context.Context, *DeleteTargetRequest) (*DeleteTargetResponse, error)
	GetTargetRuleset(context.Context, *GetTargetRulesetRequest) (*GetTargetRulesetResponse, error)
	SetTargetRuleset(context.Context, *SetTargetRulesetRequest) (*SetTargetRulesetResponse, error)
	// Certificates: import a certificate file into a secret, export a
	// certificate secret's material back out as a file, or replace a secret's
	// certificate material in place (rotation, e.g. after a CA re-issue).
	ImportCertificate(context.Context, *ImportCertificateRequest) (*ImportCertificateResponse, error)
	ExportCertificate(context.Context, *ExportCertificateRequest) (*ExportCertificateResponse, error)
	ReplaceCertificate(context.Context, *ReplaceCertificateRequest) (*ReplaceCertificateResponse, error)
	// Secret types
	ListSecretTypes(context.Context, *ListSecretTypesRequest) (*ListSecretTypesResponse, error)
	CreateSecretType(context.Context, *CreateSecretTypeRequest) (*CreateSecretTypeResponse, error)
	UpdateSecretType(context.Context, *UpdateSecretTypeRequest) (*UpdateSecretTypeResponse, error)
	DeleteSecretType(context.Context, *DeleteSecretTypeRequest) (*DeleteSecretTypeResponse, error)
	CloneSecretType(context.Context, *CloneSecretTypeRequest) (*CloneSecretTypeResponse, error)
	ListAvailableExtensions(context.Context, *ListAvailableExtensionsRequest) (*ListAvailableExtensionsResponse, error)
	ImportExtension(context.Context, *ImportExtensionRequest) (*ImportExtensionResponse, error)
	ImportExtensionFromJson(context.Context, *ImportExtensionFromJsonRequest) (*ImportExtensionFromJsonResponse, error)
	// Folders
	ListFolders(context.Context, *ListFoldersRequest) (*ListFoldersResponse, error)
	CreateFolder(context.Context, *CreateFolderRequest) (*CreateFolderResponse, error)
	RenameFolder(context.Context, *RenameFolderRequest) (*RenameFolderResponse, error)
	MoveFolder(context.Context, *MoveFolderRequest) (*MoveFolderResponse, error)
	DeleteFolder(context.Context, *DeleteFolderRequest) (*DeleteFolderResponse, error)
	ReorderFolders(context.Context, *ReorderFoldersRequest) (*ReorderFoldersResponse, error)
	// Folder RBAC (legacy FolderAccessRule API — retained for the current UI;
	// superseded by the firewall-RACI ruleset below, which is the enforcement
	// source of truth).
	ListFolderRules(context.Context, *ListFolderRulesRequest) (*ListFolderRulesResponse, error)
	GetInheritedFolderRules(context.Context, *GetInheritedFolderRulesRequest) (*GetInheritedFolderRulesResponse, error)
	AddFolderRule(context.Context, *AddFolderRuleRequest) (*AddFolderRuleResponse, error)
	RemoveFolderRule(context.Context, *RemoveFolderRuleRequest) (*RemoveFolderRuleResponse, error)
	// Firewall-RACI folder access (the authz engine): ordered rules + owners per
	// folder, evaluated down the folder chain. Enforcement source of truth.
	GetFolderRuleset(context.Context, *GetFolderRulesetRequest) (*GetFolderRulesetResponse, error)
	SetFolderRuleset(context.Context, *SetFolderRulesetRequest) (*SetFolderRulesetResponse, error)
	SetFolderRevealStepUp(context.Context, *SetFolderRevealStepUpRequest) (*SetFolderRevealStepUpResponse, error)
	GetMyAccess(context.Context, *GetMyAccessRequest) (*GetMyAccessResponse, error)
	SimulateFolder(context.Context, *SimulateFolderRequest) (*SimulateFolderResponse, error)
	SimulateSecret(context.Context, *SimulateSecretRequest) (*SimulateSecretResponse, error)
	// Secrets
	ListSecretsInFolder(context.Context, *ListSecretsInFolderRequest) (*ListSecretsInFolderResponse, error)
	// ReorderSecrets sets the manual order of a folder's active secrets. The
	// caller needs RACI Author on the folder or must own it.
	ReorderSecrets(context.Context, *ReorderSecretsRequest) (*ReorderSecretsResponse, error)
	GetSecret(context.Context, *GetSecretRequest) (*GetSecretResponse, error)
	CreateSecret(context.Context, *CreateSecretRequest) (*CreateSecretResponse, error)
	UpdateSecret(context.Context, *UpdateSecretRequest) (*UpdateSecretResponse, error)
	SetSecretAutomation(context.Context, *SetSecretAutomationRequest) (*SetSecretAutomationResponse, error)
	GetSecretFields(context.Context, *GetSecretFieldsRequest) (*GetSecretFieldsResponse, error)
	RevealSecretField(context.Context, *RevealSecretFieldRequest) (*RevealSecretFieldResponse, error)
	// Reveal for non-human principals (service accounts, workloads): RACI-read
	// + full audit, no interactive checkout/MFA.
	RevealSecretFieldForPrincipal(context.Context, *RevealSecretFieldForPrincipalRequest) (*RevealSecretFieldForPrincipalResponse, error)
	ListSecretsForPrincipal(context.Context, *ListSecretsForPrincipalRequest) (*ListSecretsForPrincipalResponse, error)
	CreateSecretForPrincipal(context.Context, *CreateSecretForPrincipalRequest) (*CreateSecretForPrincipalResponse, error)
	GenerateSecretForPrincipal(context.Context, *GenerateSecretForPrincipalRequest) (*GenerateSecretForPrincipalResponse, error)
	MoveSecretForPrincipal(context.Context, *MoveSecretForPrincipalRequest) (*MoveSecretForPrincipalResponse, error)
	ChangeSecretTypeForPrincipal(context.Context, *ChangeSecretTypeForPrincipalRequest) (*ChangeSecretTypeForPrincipalResponse, error)
	// Organize verbs for non-human principals: rename/update a secret and
	// list/create/rename/move folders. No machine delete.
	RenameSecretForPrincipal(context.Context, *RenameSecretForPrincipalRequest) (*RenameSecretForPrincipalResponse, error)
	UpdateSecretFieldsForPrincipal(context.Context, *UpdateSecretFieldsForPrincipalRequest) (*UpdateSecretFieldsForPrincipalResponse, error)
	ListFoldersForPrincipal(context.Context, *ListFoldersForPrincipalRequest) (*ListFoldersForPrincipalResponse, error)
	CreateFolderForPrincipal(context.Context, *CreateFolderForPrincipalRequest) (*CreateFolderForPrincipalResponse, error)
	RenameFolderForPrincipal(context.Context, *RenameFolderForPrincipalRequest) (*RenameFolderForPrincipalResponse, error)
	MoveFolderForPrincipal(context.Context, *MoveFolderForPrincipalRequest) (*MoveFolderForPrincipalResponse, error)
	// Per-secret value history: list prior versions (metadata + field keys) and
	// reveal a single field's value from a specific version (audited).
	ListSecretVersions(context.Context, *ListSecretVersionsRequest) (*ListSecretVersionsResponse, error)
	RevealSecretVersionField(context.Context, *RevealSecretVersionFieldRequest) (*RevealSecretVersionFieldResponse, error)
	RestoreSecretVersion(context.Context, *RestoreSecretVersionRequest) (*RestoreSecretVersionResponse, error)
	// Emergency access: bypasses checkout/approval gating for a read-eligible
	// actor; high-severity audit + owner notify + forced rotation-enqueue.
	BreakGlassSecret(context.Context, *BreakGlassSecretRequest) (*BreakGlassSecretResponse, error)
	// Break-glass browse for human site admins: open, check, list, close, and
	// the audit view of past sessions with their reveals.
	OpenBreakGlassSession(context.Context, *OpenBreakGlassSessionRequest) (*OpenBreakGlassSessionResponse, error)
	GetBreakGlassSession(context.Context, *GetBreakGlassSessionRequest) (*GetBreakGlassSessionResponse, error)
	ListBreakGlassItems(context.Context, *ListBreakGlassItemsRequest) (*ListBreakGlassItemsResponse, error)
	CloseBreakGlassSession(context.Context, *CloseBreakGlassSessionRequest) (*CloseBreakGlassSessionResponse, error)
	ListBreakGlassSessions(context.Context, *ListBreakGlassSessionsRequest) (*ListBreakGlassSessionsResponse, error)
	CopySecret(context.Context, *CopySecretRequest) (*CopySecretResponse, error)
	// Secret lifecycle: soft-retire (recoverable), restore, and hard delete (permanent).
	RetireSecret(context.Context, *RetireSecretRequest) (*RetireSecretResponse, error)
	RestoreSecret(context.Context, *RestoreSecretRequest) (*RestoreSecretResponse, error)
	DeleteSecret(context.Context, *DeleteSecretRequest) (*DeleteSecretResponse, error)
	GetSecretStats(context.Context, *GetSecretStatsRequest) (*GetSecretStatsResponse, error)
	GetTopAccessedSecrets(context.Context, *GetTopAccessedSecretsRequest) (*GetTopAccessedSecretsResponse, error)
	ListSecretsByStatus(context.Context, *ListSecretsByStatusRequest) (*ListSecretsByStatusResponse, error)
	FindSecretsByPublicKey(context.Context, *FindSecretsByPublicKeyRequest) (*FindSecretsByPublicKeyResponse, error)
	// Firewall-RACI secret access (the authz engine): ordered rules on a single
	// secret, evaluated before falling through to its folder's ruleset.
	GetSecretRuleset(context.Context, *GetSecretRulesetRequest) (*GetSecretRulesetResponse, error)
	SetSecretRuleset(context.Context, *SetSecretRulesetRequest) (*SetSecretRulesetResponse, error)
	GetMySecretAccess(context.Context, *GetMySecretAccessRequest) (*GetMySecretAccessResponse, error)
	// Connector / heartbeat — called by the connector worker, identity-gated.
	ClaimDueHeartbeats(context.Context, *ClaimDueHeartbeatsRequest) (*ClaimDueHeartbeatsResponse, error)
	RevealForHeartbeat(context.Context, *RevealForHeartbeatRequest) (*RevealForHeartbeatResponse, error)
	ReportHeartbeat(context.Context, *ReportHeartbeatRequest) (*ReportHeartbeatResponse, error)
	// Connector / rotation — called by the connector worker, identity-gated.
	EnqueueRotation(context.Context, *EnqueueRotationRequest) (*EnqueueRotationResponse, error)
	ClaimDueRotations(context.Context, *ClaimDueRotationsRequest) (*ClaimDueRotationsResponse, error)
	RevealForRotation(context.Context, *RevealForRotationRequest) (*RevealForRotationResponse, error)
	ReportRotation(context.Context, *ReportRotationRequest) (*ReportRotationResponse, error)
	// Connector builds: each connector's build (from the sneakers-version and
	// sneakers-commit metadata of its pull calls) and its last contact, for the
	// gateway's diagnostics. Caller gateway only, as itself.
	ListConnectors(context.Context, *ListConnectorsRequest) (*ListConnectorsResponse, error)
	// Instance configuration: password policies + security settings
	ListPasswordPolicies(context.Context, *ListPasswordPoliciesRequest) (*ListPasswordPoliciesResponse, error)
	SavePasswordPolicy(context.Context, *SavePasswordPolicyRequest) (*SavePasswordPolicyResponse, error)
	DeletePasswordPolicy(context.Context, *DeletePasswordPolicyRequest) (*DeletePasswordPolicyResponse, error)
	GetSecuritySettings(context.Context, *GetSecuritySettingsRequest) (*GetSecuritySettingsResponse, error)
	UpdateSecuritySettings(context.Context, *UpdateSecuritySettingsRequest) (*UpdateSecuritySettingsResponse, error)
	// Install the built-in baseline (secret types, extension catalog, default
	// password policies, connections, the master personal folder + the acting
	// admin's personal folder) into a fresh, EMPTY vault. Idempotent: safe to
	// re-run. Called by the gateway as part of first-run /setup, after the first
	// admin is created — a fresh install stays empty until this runs.
	SeedBuiltins(context.Context, *SeedBuiltinsRequest) (*SeedBuiltinsResponse, error)
	// Generate a fresh SSH keypair server-side. The private key is
	// returned once for the caller to store as a secret field; it is never
	// persisted by the vault itself.
	GenerateKeyPair(context.Context, *GenerateKeyPairRequest) (*GenerateKeyPairResponse, error)
	// Rotates the active working-KEK: mints a new KEK, activates it, and
	// sweeps existing records to re-wrap their DEKs under it.
	RotateKek(context.Context, *RotateKekRequest) (*RotateKekResponse, error)
	// Seals field sets for an import without storing them (migrate caller only).
	SealForImport(context.Context, *SealForImportRequest) (*SealForImportResponse, error)
	PrepareSecretUse(context.Context, *PrepareSecretUseRequest) (*PrepareSecretUseResponse, error)
	GetSecretUse(context.Context, *GetSecretUseRequest) (*GetSecretUseResponse, error)
	ListPendingSecretUses(context.Context, *ListPendingSecretUsesRequest) (*ListPendingSecretUsesResponse, error)
	DecideSecretUse(context.Context, *DecideSecretUseRequest) (*DecideSecretUseResponse, error)
	ConfirmSecretUse(context.Context, *ConfirmSecretUseRequest) (*ConfirmSecretUseResponse, error)
	ListSecretUsesToDecide(context.Context, *ListSecretUsesToDecideRequest) (*ListSecretUsesToDecideResponse, error)
	RedeemSecretUse(context.Context, *RedeemSecretUseRequest) (*RedeemSecretUseResponse, error)
	CreateUseGrant(context.Context, *CreateUseGrantRequest) (*CreateUseGrantResponse, error)
	ListUseGrants(context.Context, *ListUseGrantsRequest) (*ListUseGrantsResponse, error)
	RevokeUseGrant(context.Context, *RevokeUseGrantRequest) (*RevokeUseGrantResponse, error)
	SetSecretTokenApproval(context.Context, *SetSecretTokenApprovalRequest) (*SetSecretTokenApprovalResponse, error)
	SetSecretTargetForPrincipal(context.Context, *SetSecretTargetForPrincipalRequest) (*SetSecretTargetForPrincipalResponse, error)
	SetSecretAutomationForPrincipal(context.Context, *SetSecretAutomationForPrincipalRequest) (*SetSecretAutomationForPrincipalResponse, error)
	RequestHeartbeatForPrincipal(context.Context, *RequestHeartbeatForPrincipalRequest) (*RequestHeartbeatForPrincipalResponse, error)
	GetHeartbeatStatusForPrincipal(context.Context, *GetHeartbeatStatusForPrincipalRequest) (*GetHeartbeatStatusForPrincipalResponse, error)
	mustEmbedUnimplementedVaultServiceServer()
}

